    y0 = max(0, H-v-r); y1 = min(H, H-v+r)
    x0 = max(0, u-r); x1 = min(W, u+r)
    arr[y0:y1, x0:x0+2] = col; arr[y0:y1, x1-2:x1] = col
    arr[y0:y0+2, x0:x1] = col; arr[y1-2:y1, x0:x1] = col

